begin;
set local jit=off;
create function pg_temp.nl_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'MFA NL RELEASE TEST: %',message;end if;end$$;
create function pg_temp.nl_refuses(q text,expected text default 'MFA_NL_RELEASE:|MFA_NL_BOOTSTRAP:|HISTORICAL_POLICY:')returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm !~ expected then raise exception 'MFA NL RELEASE TEST: wrong refusal %',sqlerrm;end if;return;end;raise exception 'MFA NL RELEASE TEST: expected refusal';end$$;
select pg_temp.nl_assert(to_regprocedure('public.get_mfa_nl_reviewed_source_state(bigint,text,text)')is not null,'closed source-state API missing');
select pg_temp.nl_assert(private_mfa_nl_history.canonical_json('{"z":{"b":2,"a":"x"},"a":[1,true,null,"ž"]}')='{"a":[1,true,null,"ž"],"z":{"a":"x","b":2}}'and encode(sha256(convert_to(private_mfa_nl_history.canonical_json('{"z":{"b":2,"a":"x"},"a":[1,true,null,"ž"]}'),'UTF8')),'hex')='3cdf7ad5d95a23c996586a1803ff98ec2380ada7de3fbc9e26cc9753948a95b4','canonical document SHA must match independent UTF8 JSON vector');
\ir mfa-nl-release-fixture.sql
select pg_temp.nl_assert(not has_schema_privilege('service_role','private_mfa_nl_history','USAGE')and not has_table_privilege('service_role','private_mfa_nl_history.source_contract','INSERT'),'service source-contract write boundary open');
select pg_temp.nl_assert(not has_function_privilege('anon','public.record_mfa_nl_reviewed_import(bigint,text,text,text)','EXECUTE')and not has_function_privilege('authenticated','public.check_mfa_nl_reviewed_release(bigint,text,text,text,boolean)','EXECUTE'),'release wrappers exposed');
select pg_temp.nl_assert(not has_function_privilege('service_role','private_mfa_nl_history.release_core(bigint,text,text,text,boolean,timestamptz)','EXECUTE'),'private clock core exposed');
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_contract(974,repeat(''f'',64))');
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_state(974,repeat(''e'',40),repeat(''f'',64))');
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_import(974,repeat(''e'',40),repeat(''f'',64),repeat(''f'',64))');
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_prices(974,repeat(''e'',40),repeat(''f'',64))');
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),repeat(''f'',64))');
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_release_receipt(974)');
-- Every altered authoritative header/count/artifact/hash must hold before import.
do $$declare changed jsonb;begin
 for changed in select jsonb_set(document,path,value)from nl_release_contracts cross join(values
 ('{reports,0,homeGoals}'::text[],'9'::jsonb),('{reports,0,reportId}','"mt999999999"'),('{reports,0,homeName}','"Wrong club"'),
 ('{currentFixtures,0,round}','99'),('{expectedArchiveRounds}','5'),('{expectedCurrentFixtureCount}','7'),('{expectedCurrentClubCount}','7'),('{sourceArtifact,commit}','"wrong"'),('{opening,deadlineAt}','"2026-11-01T11:00:00Z"'),('{opening,round}','3'))v(path,value)where cid=974 loop
  begin
   insert into private_mfa_nl_history.source_contract values(974,encode(sha256(convert_to(private_mfa_nl_history.canonical_json(changed),'UTF8')),'hex'),changed);
   perform pg_temp.nl_refuses(format('select public.get_mfa_nl_reviewed_source_state(974,%L,%L)',repeat('e',40),encode(sha256(convert_to(private_mfa_nl_history.canonical_json(changed),'UTF8')),'hex')));
   raise exception using errcode='P9001',message='rollback synthetic contract';
  exception when sqlstate 'P9001'then null;end;
 end loop;
end$$;
insert into private_mfa_nl_history.source_contract select cid,pg_temp.nl_contract_sha(cid),document from nl_release_contracts;
select pg_temp.nl_refuses('update private_mfa_nl_history.source_contract set document=jsonb_set(document,''{sourceArtifact,branch}'',''"changed"'')where competition_id=974');
select pg_temp.nl_refuses('delete from private_mfa_nl_history.source_contract where competition_id=974');
select pg_temp.nl_assert(public.get_mfa_nl_reviewed_source_contract(974,pg_temp.nl_contract_sha(974))->'contractDocument'=(select document from nl_release_contracts where cid=974),'service must authenticate exact contract');
grant execute on function pg_temp.nl_assert(boolean,text),pg_temp.nl_refuses(text,text)to anon,authenticated,service_role;
select set_config('slff.nl_test_contract_sha',pg_temp.nl_contract_sha(974),true);
set local role anon;
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_contract(974,repeat(''f'',64))','permission denied');
reset role;
set local role authenticated;
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),repeat(''f'',64))','permission denied');
reset role;
set local role service_role;
select pg_temp.nl_refuses('select private_mfa_nl_history.football_image(974)','permission denied');
select pg_temp.nl_refuses('select *from private_mfa_nl_history.source_contract','permission denied');
select pg_temp.nl_assert(public.get_mfa_nl_reviewed_source_contract(974,current_setting('slff.nl_test_contract_sha'))->>'competitionId'='974','service contract accessor denied');
reset role;
create temporary table nl_source_states as select cid,public.get_mfa_nl_reviewed_source_state(cid,repeat('e',40),pg_temp.nl_contract_sha(cid))as state from(values(973),(974))v(cid);
select pg_temp.nl_assert(not exists(select 1 from nl_source_states where state->>'footballSha256'<>encode(sha256(convert_to(state->>'footballImageText','UTF8')),'hex')),'exact unreserialized native football bytes must bind SHA');
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_import(974,repeat(''e'',40),pg_temp.nl_contract_sha(974),repeat(''0'',64))');
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_prices(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
select public.record_mfa_nl_reviewed_import(cid,repeat('e',40),pg_temp.nl_contract_sha(cid),state->>'footballSha256')from nl_source_states;
-- Normal position/price/active fields are pricing outputs, never source identity.
update players set position=case when reg_st%100=1 then'GK'when reg_st%100<=5 then'DEF'when reg_st%100<=10 then'MID'else'FWD'end,position_source=case when reg_st%100=1 then'zapisnik'else'ugibanje'end,value=case when reg_st%100=2 then 8 else 4 end,value_start=case when reg_st%100=2 then 8 else 4 end where competition_id in(973,974);
select pg_temp.nl_assert(not exists(select 1 from nl_source_states s where(public.get_mfa_nl_reviewed_source_state(cid,repeat('e',40),pg_temp.nl_contract_sha(cid))->>'footballSha256')is distinct from s.state->>'footballSha256'),'pricing unexpectedly changed football source snapshot');
select public.record_mfa_nl_reviewed_prices(cid,repeat('e',40),pg_temp.nl_contract_sha(cid))from nl_source_states;
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_prices(974,repeat(''d'',40),pg_temp.nl_contract_sha(974))');
create temporary table nl_previews as select cid,public.check_mfa_nl_reviewed_release(cid,repeat('e',40),pg_temp.nl_contract_sha(cid))as result from nl_source_states;
select pg_temp.nl_refuses('update competitions set active=true where id=974');
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974),repeat(''0'',64),true)');
select pg_temp.nl_refuses('select private_mfa_nl_history.release_core(974,repeat(''e'',40),pg_temp.nl_contract_sha(974),null,false,''2026-11-01T10:00Z'')');
savepoint repriced_same_state;
select public.record_mfa_nl_reviewed_prices(974,repeat('e',40),pg_temp.nl_contract_sha(974));
select pg_temp.nl_refuses(format('select public.check_mfa_nl_reviewed_release(974,%L,%L,%L,true)',repeat('e',40),pg_temp.nl_contract_sha(974),result->>'previewSha256'))from nl_previews where cid=974;
rollback to savepoint repriced_same_state;
savepoint late_activity;
insert into auth.users(id,email,raw_user_meta_data,created_at)values('f0000000-0000-0000-0000-000000000974','release974@example.test','{"display_name":"Release fixture"}',now());
insert into fantasy_teams(owner_id,name,competition_id)values('f0000000-0000-0000-0000-000000000974','Release dependency',974);
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint late_activity;
savepoint late_deleted_vote;
insert into position_votes_deleted(id,player_id)select 9900001,min(id)from players where competition_id=974;
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint late_deleted_vote;
savepoint bad_xi;
delete from appearances where id=(select min(a.id)from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=974 and a.started);
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_state(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint bad_xi;
savepoint bad_minutes;
update appearances set minute_off=89 where id=(select min(a.id)from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=974);
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_state(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint bad_minutes;
savepoint extra_pending;
insert into matches(round_id,home_team_id,away_team_id,played_on)values(9740002,9909742,9909743,'2026-11-01');
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_state(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint extra_pending;
savepoint source_drift;
update players set full_name='Source identity changed'where id=(select min(id)from players where competition_id=974);
select pg_temp.nl_refuses(format('select public.record_mfa_nl_reviewed_import(974,%L,%L,%L)',repeat('e',40),pg_temp.nl_contract_sha(974),public.get_mfa_nl_reviewed_source_state(974,repeat('e',40),pg_temp.nl_contract_sha(974))->>'footballSha256'));
select pg_temp.nl_refuses('select public.record_mfa_nl_reviewed_prices(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint source_drift;

savepoint stale_price;
update players set value=value+0.5 where id=(select min(id)from players where competition_id=974);
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint stale_price;
savepoint gk_missing;
update players set position_source='ugibanje'where competition_id=974 and team_id=9909741 and position='GK';
select public.record_mfa_nl_reviewed_prices(974,repeat('e',40),pg_temp.nl_contract_sha(974));
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint gk_missing;
savepoint expensive;
update players set value=50 where competition_id=974;
select public.record_mfa_nl_reviewed_prices(974,repeat('e',40),pg_temp.nl_contract_sha(974));
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint expensive;
savepoint default_prices;
update players set value=case when reg_st%100=2 then 8 else 4.5 end where competition_id=974;
select public.record_mfa_nl_reviewed_prices(974,repeat('e',40),pg_temp.nl_contract_sha(974));
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint default_prices;
savepoint opening_drift;
update rounds set deadline_at=deadline_at+interval '1 hour'where id=9740002;
select pg_temp.nl_refuses('select public.check_mfa_nl_reviewed_release(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint opening_drift;
savepoint missing_report;
update matches set zapisnik_id='mt999999999',source_url='https://matchcentre.mfa.com.mt/match/999999999'where id=9740001;
select pg_temp.nl_refuses('select public.get_mfa_nl_reviewed_source_state(974,repeat(''e'',40),pg_temp.nl_contract_sha(974))');
rollback to savepoint missing_report;
-- Failure after native active=true must roll back the row and one-use authorization.
create function pg_temp.nl_release_failure()returns trigger language plpgsql as $$begin if new.competition_id=974 then raise exception 'MFA_NL_RELEASE: injected late receipt failure';end if;return new;end$$;
create trigger nl_release_test_failure before insert on private_mfa_nl_history.release_receipt for each row execute function pg_temp.nl_release_failure();
select pg_temp.nl_refuses(format('select public.check_mfa_nl_reviewed_release(974,%L,%L,%L,true)',repeat('e',40),pg_temp.nl_contract_sha(974),result->>'previewSha256'))from nl_previews where cid=974;
drop trigger nl_release_test_failure on private_mfa_nl_history.release_receipt;
select pg_temp.nl_assert((select not active from competitions where id=974)and not exists(select 1 from private_mfa_nl_history.release_receipt where competition_id=974)and not exists(select 1 from private_historical_statistics.release_authorizations where competition_id=974),'late receipt failure left partial activation/authorization');
select pg_temp.nl_refuses('update competitions set active=true where id=974');
select public.check_mfa_nl_reviewed_release(cid,repeat('e',40),pg_temp.nl_contract_sha(cid),result->>'previewSha256',true)from nl_previews;
select pg_temp.nl_assert((select count(*)from competitions where id in(973,974)and active)=2,'both exact native candidates must activate through guarded transaction');
select pg_temp.nl_assert(public.get_mfa_nl_reviewed_release_receipt(974)->'release' is not null,'ambiguous response must have recovery receipt');
rollback;
